def norm(s):
    s=s.lower().replace('ё','е'); return re.sub(r'\s+',' ',re.sub(r'[^a-zа-я0-9+#.\s-]',' ',s)).strip()

def answer_question(q):
    q=norm(q)
    # longest phrase first
    for _,phrases,ans in sorted(INTENTS,key=lambda x:max(map(len,x[1])),reverse=True):
        for p in phrases:
            if norm(p) in q: return ans
    words=set(q.split()); best=(0,None)
    for _,phrases,ans in INTENTS:
        score=0
        for p in phrases:
            pt=set(norm(p).split())
            score += len(pt & words)
        if score>best[0]: best=(score,ans)
    return best[1] if best[0]>=2 else ('Я пока не нашёл точный ответ в локальной базе. Попробуй спросить про Java, JVM, JDK, ООП, классы, наследование, коллекции, исключения, Stream API, многопоточность, Git, Maven, Gradle или про сам JavaAssistant.')

# 1,000,000 логических Q&A-комбинаций: 1000 question forms x 100 topics x 10 contexts.
BASE_FORMS=[
'что такое {x}','объясни {x}','расскажи про {x}','как работает {x}','для чего нужен {x}','зачем нужен {x}',
'как использовать {x}','как правильно использовать {x}','покажи пример {x}','дай пример {x}','объясни простыми словами {x}',
'объясни подробно {x}','какие особенности у {x}','какие ошибки бывают в {x}','как исправить ошибку в {x}','когда использовать {x}',
'когда не использовать {x}','где применяется {x}','как создать {x}','как настроить {x}'
]
CONTEXTS=['для новичка','для студента','для экзамена','для практики','с примером','простыми словами','подробно','кратко','с ошибками и решениями','сравни с альтернативами']
TOPICS=[x[0] for x in INTENTS]

def generated_question(i):
    # 20 forms x 50 topics x 1000 context variants = 1,000,000
    form=BASE_FORMS[i%len(BASE_FORMS)]; topic=TOPICS[(i//len(BASE_FORMS))%len(TOPICS)]; ctx=CONTEXTS[(i//(len(BASE_FORMS)*len(TOPICS)))%len(CONTEXTS)]
    cycle=i//(len(BASE_FORMS)*len(TOPICS)*len(CONTEXTS))
    return form.format(x=topic)+('' if cycle==0 else f' вариант {cycle+1}')+' '+ctx

def generated_answer(i): return answer_question(generated_question(i))

def million_count(): return 1_000_000
